package db

import (
	"testing"
)

func TestDB_MigrationIdempotency(t *testing.T) {
	// 1. Open database (triggers initial migration)
	db, err := Open(":memory:")
	if err != nil {
		t.Fatalf("Open failed: %v", err)
	}
	defer db.Close()

	// 2. Verify schema version after first run
	v1, err := currentSchemaVersion(db)
	if err != nil {
		t.Fatalf("failed to read schema version: %v", err)
	}
	if v1 == 0 {
		t.Errorf("expected schema version > 0, got %d", v1)
	}

	// 3. Execute Migrate directly again to ensure safety/idempotency
	if err := Migrate(db); err != nil {
		t.Fatalf("subsequent migration failed: %v", err)
	}

	// 4. Confirm schema version remained unchanged
	v2, err := currentSchemaVersion(db)
	if err != nil {
		t.Fatalf("failed to re-read schema version: %v", err)
	}
	if v1 != v2 {
		t.Errorf("schema version changed unexpectedly: before %d, after %d", v1, v2)
	}

	// 5. Query expected table columns to verify schema state
	var expiresAtExists bool
	rows, err := db.Query("PRAGMA table_info(links);")
	if err != nil {
		t.Fatalf("failed to inspect links table schema: %v", err)
	}
	defer rows.Close()

	for rows.Next() {
		var cid int
		var name, typeStr string
		var notNull, pk int
		var dfltValue any
		if err := rows.Scan(&cid, &name, &typeStr, &notNull, &dfltValue, &pk); err != nil {
			t.Fatalf("failed scanning column info: %v", err)
		}
		if name == "expires_at" {
			expiresAtExists = true
		}
	}

	if !expiresAtExists {
		t.Error("expected 'expires_at' column in 'links' table from migration 002")
	}
}



package db

import (
	"errors"

	"github.com/ncruces/go-sqlite3"
)

func IsUniqueConstraintError(err error) bool {
	var sqliteErr *sqlite3.Error

	if !errors.As(err, &sqliteErr) {
		return false
	}

	return sqliteErr.Code() == sqlite3.CONSTRAINT &&
		sqliteErr.ExtendedCode() == sqlite3.CONSTRAINT_UNIQUE
}



package link

import (
	"database/sql"
	"fmt"
	"sync"
	"testing"
	"time"

	_ "github.com/ncruces/go-sqlite3/driver"
)

func setupTestDB(t *testing.T) *sql.DB {
	t.Helper()
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		t.Fatalf("failed to open memory db: %v", err)
	}

	_, err = db.Exec(`
		CREATE TABLE links (id INTEGER PRIMARY KEY, click_count INTEGER DEFAULT 0);
		CREATE TABLE link_clicks (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			link_id INTEGER NOT NULL,
			referer TEXT,
			user_agent TEXT,
			clicked_at DATETIME DEFAULT CURRENT_TIMESTAMP
		);
		INSERT INTO links (id, click_count) VALUES (1, 0);
	`)
	if err != nil {
		t.Fatalf("failed to setup schema: %v", err)
	}

	return db
}

func TestClickTracker_ConcurrencyAndShutdown(t *testing.T) {
	db := setupTestDB(t)
	defer db.Close()

	tracker := newClickTracker(db)

	const numWorkers = 10
	const clicksPerWorker = 200

	var wg sync.WaitGroup
	startSignal := make(chan struct{})

	// Spin up workers sending events concurrently
	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			<-startSignal // Sync start for max concurrency

			for j := 0; j < clicksPerWorker; j++ {
				tracker.record(ClickEvent{
					LinkID:    1,
					Referer:   fmt.Sprintf("http://example.com/%d", workerID),
					UserAgent: "TestAgent/1.0",
					ClickedAt: time.Now(),
				})
			}
		}(i)
	}

	close(startSignal) // Trigger workers

	// Trigger shutdown concurrently while workers are sending
	time.Sleep(5 * time.Millisecond)
	tracker.close()

	// Ensure no goroutine deadlocks or panics on closed channels
	wg.Wait()

	// Verify idempotency on repeated close calls
	tracker.close()
}



package link

import (
	"errors"
	"net/http"
	"strconv"

	"url-shortener/internal/platform/utils"
)

type Handler struct {
	service Service
}

func NewHandler(svc Service) *Handler {
	return &Handler{service: svc}
}

func (h *Handler) RegisterRoutes(mux *http.ServeMux) {
	mux.HandleFunc("POST /api/shorten", h.handleShorten)
	mux.HandleFunc("GET /api/links", h.handleListLinks)
	mux.HandleFunc("GET /api/links/{id}", h.handleGetLink)
	mux.HandleFunc("GET /api/links/{id}/clicks", h.handleListClicks)
	mux.HandleFunc("GET /api/links/{id}/clicks/{clickID}", h.handleGetClick)
}

func (h *Handler) handleShorten(w http.ResponseWriter, r *http.Request) {
	var req CreateLinkRequest
	if err := utils.ParseJSON(w, r, &req); err != nil || req.DestinationURL == "" {
		http.Error(w, `{"error":"Invalid payload"}`, http.StatusBadRequest)
		return
	}

	created, err := h.service.Create(r.Context(), req)
	if err != nil {
		switch {
		case errors.Is(err, ErrInvalidURL):
			http.Error(w, `{"error":"Invalid destination URL"}`, http.StatusBadRequest)
		case errors.Is(err, ErrReservedSlug):
			http.Error(w, `{"error":"Slug is a reserved path"}`, http.StatusBadRequest)
		case errors.Is(err, ErrSlugExists):
			http.Error(w, `{"error":"Slug already exists"}`, http.StatusConflict)
		default:
			http.Error(w, `{"error":"Database error"}`, http.StatusInternalServerError)
		}
		return
	}

	utils.WriteJSON(w, http.StatusCreated, created)
}

func (h *Handler) handleListLinks(w http.ResponseWriter, r *http.Request) {
	links, err := h.service.List(r.Context())
	if err != nil {
		http.Error(w, `{"error":"Database error"}`, http.StatusInternalServerError)
		return
	}
	utils.WriteJSON(w, http.StatusOK, links)
}

func (h *Handler) handleGetLink(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil {
		http.Error(w, `{"error":"Invalid link ID"}`, http.StatusBadRequest)
		return
	}

	l, err := h.service.GetByID(r.Context(), id)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			http.Error(w, `{"error":"Link not found"}`, http.StatusNotFound)
			return
		}
		http.Error(w, `{"error":"Database error"}`, http.StatusInternalServerError)
		return
	}

	utils.WriteJSON(w, http.StatusOK, l)
}

func (h *Handler) handleListClicks(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil {
		http.Error(w, `{"error":"Invalid link ID"}`, http.StatusBadRequest)
		return
	}

	clicks, err := h.service.ListClicks(r.Context(), id)
	if err != nil {
		http.Error(w, `{"error":"Database error"}`, http.StatusInternalServerError)
		return
	}

	utils.WriteJSON(w, http.StatusOK, clicks)
}

func (h *Handler) handleGetClick(w http.ResponseWriter, r *http.Request) {
	clickID, err := strconv.ParseInt(r.PathValue("clickID"), 10, 64)
	if err != nil {
		http.Error(w, `{"error":"Invalid click ID"}`, http.StatusBadRequest)
		return
	}

	click, err := h.service.GetClickByID(r.Context(), clickID)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			http.Error(w, `{"error":"Click not found"}`, http.StatusNotFound)
			return
		}
		http.Error(w, `{"error":"Database error"}`, http.StatusInternalServerError)
		return
	}

	utils.WriteJSON(w, http.StatusOK, click)
}



package link

import (
	"context"
	"database/sql"
	"time"
)

type Repository interface {
	Create(ctx context.Context, slug, dest string, isCustom bool, exp *time.Time) (Link, error)
	GetByID(ctx context.Context, id int64) (Link, bool, error)
	GetBySlug(ctx context.Context, slug string) (Link, bool, error)
	List(ctx context.Context) ([]Link, error)

	RecordClick(event ClickEvent)
	GetClickByID(ctx context.Context, id int64) (ClickEvent, bool, error)
	ListClicksByLinkID(ctx context.Context, linkID int64) ([]ClickEvent, error)
	Close()
}

type sqliteRepository struct {
	db     *sql.DB
	clicks *clickTracker
}

func NewRepository(database *sql.DB) Repository {
	return &sqliteRepository{
		db:     database,
		clicks: newClickTracker(database),
	}
}

func (r *sqliteRepository) Create(ctx context.Context, slug, dest string, isCustom bool, exp *time.Time) (Link, error) {
	query := `
        INSERT INTO links (slug, destination_url, is_custom, expires_at)
        VALUES (?, ?, ?, ?)
        RETURNING id, slug, destination_url, is_custom, click_count, created_at, expires_at
    `
	var l Link
	err := r.db.QueryRowContext(ctx, query, slug, dest, isCustom, exp).Scan(
		&l.ID, &l.Slug, &l.DestinationURL, &l.IsCustom, &l.ClickCount, &l.CreatedAt, &l.ExpiresAt,
	)
	return l, err
}

func (r *sqliteRepository) GetByID(ctx context.Context, id int64) (Link, bool, error) {
	var l Link
	err := r.db.QueryRowContext(ctx, `
        SELECT id, slug, destination_url, is_custom, click_count, created_at, expires_at
        FROM links WHERE id = ?
    `, id).Scan(&l.ID, &l.Slug, &l.DestinationURL, &l.IsCustom, &l.ClickCount, &l.CreatedAt, &l.ExpiresAt)

	if err == sql.ErrNoRows {
		return Link{}, false, nil
	}
	return l, err == nil, err
}

func (r *sqliteRepository) GetBySlug(ctx context.Context, slug string) (Link, bool, error) {
	var l Link
	err := r.db.QueryRowContext(ctx, `
        SELECT id, slug, destination_url, is_custom, click_count, created_at, expires_at
        FROM links WHERE slug = ? AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)
    `, slug).Scan(&l.ID, &l.Slug, &l.DestinationURL, &l.IsCustom, &l.ClickCount, &l.CreatedAt, &l.ExpiresAt)

	if err == sql.ErrNoRows {
		return Link{}, false, nil
	}
	return l, err == nil, err
}

func (r *sqliteRepository) List(ctx context.Context) ([]Link, error) {
	rows, err := r.db.QueryContext(ctx, `
        SELECT id, slug, destination_url, is_custom, click_count, created_at, expires_at
        FROM links ORDER BY id DESC
    `)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var links []Link
	for rows.Next() {
		var l Link
		if err := rows.Scan(&l.ID, &l.Slug, &l.DestinationURL, &l.IsCustom, &l.ClickCount, &l.CreatedAt, &l.ExpiresAt); err != nil {
			return nil, err
		}
		links = append(links, l)
	}
	return links, rows.Err()
}

func (r *sqliteRepository) RecordClick(event ClickEvent) {
	r.clicks.record(event)
}

func (r *sqliteRepository) GetClickByID(ctx context.Context, id int64) (ClickEvent, bool, error) {
	var c ClickEvent
	err := r.db.QueryRowContext(ctx, `
        SELECT id, link_id, referer, user_agent, clicked_at FROM link_clicks WHERE id = ?
    `, id).Scan(&c.ID, &c.LinkID, &c.Referer, &c.UserAgent, &c.ClickedAt)

	if err == sql.ErrNoRows {
		return ClickEvent{}, false, nil
	}
	return c, err == nil, err
}

func (r *sqliteRepository) ListClicksByLinkID(ctx context.Context, linkID int64) ([]ClickEvent, error) {
	rows, err := r.db.QueryContext(ctx, `
        SELECT id, link_id, referer, user_agent, clicked_at FROM link_clicks
        WHERE link_id = ? ORDER BY clicked_at DESC
    `, linkID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var clicks []ClickEvent
	for rows.Next() {
		var c ClickEvent
		if err := rows.Scan(&c.ID, &c.LinkID, &c.Referer, &c.UserAgent, &c.ClickedAt); err != nil {
			return nil, err
		}
		clicks = append(clicks, c)
	}
	return clicks, rows.Err()
}

func (r *sqliteRepository) Close() {
	r.clicks.close()
}



package link

import (
	"context"
	"crypto/rand"
	"errors"
	"fmt"
	"math/big"
	"net/url"
	"strings"
	"time"

	"url-shortener/internal/db"

	lru "github.com/hashicorp/golang-lru/v2"
)

const base62Chars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

var (
	ErrInvalidURL   = errors.New("invalid destination URL")
	ErrReservedSlug = errors.New("slug is a reserved path")
	ErrSlugExists   = errors.New("slug already exists")
	ErrNotFound     = errors.New("resource not found")
)

type Service interface {
	Create(ctx context.Context, req CreateLinkRequest) (Link, error)
	GetByID(ctx context.Context, id int64) (Link, error)
	List(ctx context.Context) ([]Link, error)
	Resolve(ctx context.Context, fullPath string) (Link, string, error)

	RecordClick(event ClickEvent)
	GetClickByID(ctx context.Context, id int64) (ClickEvent, error)
	ListClicks(ctx context.Context, linkID int64) ([]ClickEvent, error)
	Close()
}

type service struct {
	repo  Repository
	cache *lru.Cache[string, Link]
}

func NewService(repo Repository, cacheSize int) (Service, error) {
	cache, err := lru.New[string, Link](cacheSize)
	if err != nil {
		return nil, err
	}
	return &service{repo: repo, cache: cache}, nil
}

func (s *service) Create(ctx context.Context, req CreateLinkRequest) (Link, error) {
	parsed, err := url.ParseRequestURI(req.DestinationURL)
	if err != nil || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		return Link{}, ErrInvalidURL
	}

	slug := strings.Trim(strings.TrimSpace(req.Slug), "/")
	isCustom := slug != ""

	if isCustom && isReservedSlug(slug) {
		return Link{}, ErrReservedSlug
	}

	for {
		if slug == "" {
			var err error
			slug, err = generateBase62ID(6)
			if err != nil {
				return Link{}, err
			}
		}

		created, err := s.repo.Create(ctx, slug, req.DestinationURL, isCustom, req.ExpiresAt)
		if err == nil {
			s.cache.Add(created.Slug, created)
			return created, nil
		}

		if isCustom || !db.IsUniqueConstraintError(err) {
			if db.IsUniqueConstraintError(err) {
				return Link{}, ErrSlugExists
			}
			return Link{}, err
		}

		slug = ""
	}
}

func (s *service) GetByID(ctx context.Context, id int64) (Link, error) {
	l, found, err := s.repo.GetByID(ctx, id)
	if err != nil {
		return Link{}, err
	}
	if !found {
		return Link{}, ErrNotFound
	}
	return l, nil
}

func (s *service) List(ctx context.Context) ([]Link, error) {
	return s.repo.List(ctx)
}

func (s *service) Resolve(ctx context.Context, fullPath string) (Link, string, error) {
	if l, ok := s.cache.Get(fullPath); ok {
		if l.ExpiresAt == nil || l.ExpiresAt.After(time.Now()) {
			return l, "", nil
		}
		s.cache.Remove(fullPath)
	}

	currentPath := fullPath
	for {
		l, found, err := s.repo.GetBySlug(ctx, currentPath)
		if err != nil {
			return Link{}, "", err
		}

		if found {
			extraPath := strings.TrimPrefix(fullPath, currentPath)
			s.cache.Add(currentPath, l)
			return l, extraPath, nil
		}

		idx := strings.LastIndex(currentPath, "/")
		if idx == -1 {
			break
		}
		currentPath = currentPath[:idx]
	}

	return Link{}, "", ErrNotFound
}

func (s *service) RecordClick(event ClickEvent) {
	s.repo.RecordClick(event)
}

func (s *service) GetClickByID(ctx context.Context, id int64) (ClickEvent, error) {
	c, found, err := s.repo.GetClickByID(ctx, id)
	if err != nil {
		return ClickEvent{}, err
	}
	if !found {
		return ClickEvent{}, ErrNotFound
	}
	return c, nil
}

func (s *service) ListClicks(ctx context.Context, linkID int64) ([]ClickEvent, error) {
	return s.repo.ListClicksByLinkID(ctx, linkID)
}

func (s *service) Close() {
	s.repo.Close()
}

func generateBase62ID(length int) (string, error) {
	b := make([]byte, length)
	max := big.NewInt(int64(len(base62Chars)))
	for i := range b {
		n, err := rand.Int(rand.Reader, max)
		if err != nil {
			return "", fmt.Errorf("failed to generate random ID: %w", err)
		}
		b[i] = base62Chars[n.Int64()]
	}
	return string(b), nil
}

func isReservedSlug(slug string) bool {
	switch slug {
	case "api", "_health", "_app":
		return true
	}
	return strings.HasPrefix(slug, "api/")
}



package middleware

import (
	"log"
	"net/http"
	"time"
)

type Middleware func(http.Handler) http.Handler

func Chain(h http.Handler, middlewares ...Middleware) http.Handler {
	for i := len(middlewares) - 1; i >= 0; i-- {
		h = middlewares[i](h)
	}
	return h
}

func Logger(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		wrapped := &responseWriter{ResponseWriter: w, statusCode: http.StatusOK}

		next.ServeHTTP(wrapped, r)

		log.Printf("%s %s %d %s", r.Method, r.URL.Path, wrapped.statusCode, time.Since(start))
	})
}

func Recoverer(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if err := recover(); err != nil {
				log.Printf("panic recovered: %v", err)
				http.Error(w, `{"error":"Internal Server Error"}`, http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

type responseWriter struct {
	http.ResponseWriter
	statusCode int
}

func (rw *responseWriter) WriteHeader(code int) {
	rw.statusCode = code
	rw.ResponseWriter.WriteHeader(code)
}



package utils

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
)

type ErrorResponse struct {
	Error string `json:"error"`
}

func ParseJSON(w http.ResponseWriter, r *http.Request, dst any) error {
	r.Body = http.MaxBytesReader(w, r.Body, 1048576)

	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()

	if err := dec.Decode(dst); err != nil {
		var syntaxErr *json.SyntaxError
		var unmarshalTypeErr *json.UnmarshalTypeError

		switch {
		case errors.As(err, &syntaxErr):
			return fmt.Errorf("body contains badly-formed JSON (at character %d)", syntaxErr.Offset)
		case errors.Is(err, io.ErrUnexpectedEOF):
			return errors.New("body contains badly-formed JSON")
		case errors.As(err, &unmarshalTypeErr):
			if unmarshalTypeErr.Field != "" {
				return fmt.Errorf("body contains incorrect JSON type for field %q", unmarshalTypeErr.Field)
			}
			return fmt.Errorf("body contains incorrect JSON type (at character %d)", unmarshalTypeErr.Offset)
		case errors.Is(err, io.EOF):
			return errors.New("body must not be empty")
		default:
			return err
		}
	}

	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		return errors.New("body must only contain a single JSON object")
	}

	return nil
}

func WriteJSON(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)

	if err := json.NewEncoder(w).Encode(data); err != nil {
		http.Error(w, `{"error":"failed to encode response"}`, http.StatusInternalServerError)
	}
}



package config

import (
	"os"
	"strconv"
)

type Config struct {
	Port        string
	DatabaseURL string
	CacheSize   int
}

func Load() *Config {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "data.db"
	}

	cacheSize := 1000
	if val := os.Getenv("CACHE_SIZE"); val != "" {
		if parsed, err := strconv.Atoi(val); err == nil && parsed > 0 {
			cacheSize = parsed
		}
	}

	return &Config{
		Port:        port,
		DatabaseURL: dbURL,
		CacheSize:   cacheSize,
	}
}



CREATE TABLE IF NOT EXISTS links (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT NOT NULL UNIQUE CHECK(length(slug) <= 255),
    destination_url TEXT NOT NULL,
    is_custom INTEGER NOT NULL DEFAULT 0,
    click_count INTEGER NOT NULL DEFAULT 0,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_links_slug
ON links(slug);

CREATE TABLE IF NOT EXISTS link_clicks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    link_id INTEGER NOT NULL REFERENCES links(id) ON DELETE CASCADE,
    referer TEXT,
    user_agent TEXT,
    clicked_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);



package db

import (
	"context"
	"database/sql"
	"fmt"
	"reflect"
)

func Scan[T any](scanner interface {
	Scan(dest ...any) error
}) (T, error) {
	var result T
	value := reflect.ValueOf(&result).Elem()

	if value.Kind() != reflect.Struct {
		return result, fmt.Errorf("db.Scan requires a struct type")
	}

	dest, err := scanDestinations(value)
	if err != nil {
		return result, err
	}

	if err := scanner.Scan(dest...); err != nil {
		return result, err
	}

	return result, nil
}

func scanDestinations(value reflect.Value) ([]any, error) {
	typeInfo := value.Type()
	dest := make([]any, 0, value.NumField())

	for i := 0; i < value.NumField(); i++ {
		fieldInfo := typeInfo.Field(i)

		if fieldInfo.PkgPath != "" || fieldInfo.Tag.Get("db") == "-" {
			continue
		}

		field := value.Field(i)
		if !field.CanAddr() {
			return nil, fmt.Errorf("db.Scan cannot address field %q", fieldInfo.Name)
		}

		dest = append(dest, field.Addr().Interface())
	}

	return dest, nil
}

func List[T any](
	ctx context.Context,
	db *sql.DB,
	query string,
	args ...any,
) ([]T, error) {
	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	items := make([]T, 0)

	for rows.Next() {
		item, err := Scan[T](rows)
		if err != nil {
			return nil, err
		}

		items = append(items, item)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

func GetByID[T any](
	ctx context.Context,
	db *sql.DB,
	query string,
	id int64,
) (T, bool, error) {
	var zero T

	item, err := Scan[T](
		db.QueryRowContext(ctx, query, id),
	)

	if err == sql.ErrNoRows {
		return zero, false, nil
	}

	if err != nil {
		return zero, false, err
	}

	return item, true, nil
}



package link

import (
	"database/sql"
	"log"
	"sync"
	"time"
)

const (
	clickBatchSize     = 100
	clickBufferSize    = 2000
	clickFlushInterval = 2 * time.Second
)

type clickTracker struct {
	db     *sql.DB
	events chan ClickEvent
	done   chan struct{}
	wg     sync.WaitGroup
	once   sync.Once
}

func newClickTracker(db *sql.DB) *clickTracker {
	tracker := &clickTracker{
		db:     db,
		events: make(chan ClickEvent, clickBufferSize),
		done:   make(chan struct{}),
	}

	tracker.wg.Add(1)
	go tracker.process()

	return tracker
}

func (t *clickTracker) record(event ClickEvent) {
	select {
	case <-t.done:
		return
	default:
	}

	timer := time.NewTimer(50 * time.Millisecond)
	defer timer.Stop()

	select {
	case t.events <- event:
	case <-t.done:
	case <-timer.C:
		log.Printf("warning: click tracker buffer full, dropped click for link_id: %d", event.LinkID)
	}
}

func (t *clickTracker) close() {
	t.once.Do(func() {
		close(t.done)
		t.wg.Wait()
	})
}

func (t *clickTracker) process() {
	defer t.wg.Done()

	ticker := time.NewTicker(clickFlushInterval)
	defer ticker.Stop()

	batch := make([]ClickEvent, 0, clickBatchSize)

	flush := func() {
		if len(batch) == 0 {
			return
		}
		if err := t.flush(batch); err != nil {
			log.Printf("error flushing clicks: %v", err)
			return
		}
		batch = batch[:0]
	}

	for {
		select {
		case <-t.done:
			for {
				select {
				case event := <-t.events:
					batch = append(batch, event)
					if len(batch) >= clickBatchSize {
						flush()
					}
				default:
					flush()
					return
				}
			}
		case event := <-t.events:
			batch = append(batch, event)
			if len(batch) >= clickBatchSize {
				flush()
			}
		case <-ticker.C:
			flush()
		}
	}
}

func (t *clickTracker) flush(batch []ClickEvent) error {
	tx, err := t.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	stmtClick, err := tx.Prepare(`
        INSERT INTO link_clicks (link_id, referer, user_agent, clicked_at)
        VALUES (?, ?, ?, ?)
    `)
	if err != nil {
		return err
	}
	defer stmtClick.Close()

	stmtCount, err := tx.Prepare(`
        UPDATE links SET click_count = click_count + 1 WHERE id = ?
    `)
	if err != nil {
		return err
	}
	defer stmtCount.Close()

	for _, click := range batch {
		if _, err := stmtClick.Exec(click.LinkID, click.Referer, click.UserAgent, click.ClickedAt); err != nil {
			return err
		}
		if _, err := stmtCount.Exec(click.LinkID); err != nil {
			return err
		}
	}

	return tx.Commit()
}



