package db

import (
	"database/sql"
	"embed"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	_ "github.com/ncruces/go-sqlite3/driver"
)

//go:embed migrations/*.sql
var migrations embed.FS

func Open(dbPath string) (*sql.DB, error) {
	dir := filepath.Dir(dbPath)

	if dir != "" && dir != "." {
		if err := os.MkdirAll(dir, 0755); err != nil {
			return nil, fmt.Errorf(
				"creating database directory '%s': %w",
				dir,
				err,
			)
		}
	}

	db, err := sql.Open("sqlite3", dbPath)
	if err != nil {
		return nil, err
	}

	db.SetMaxOpenConns(10)
	db.SetMaxIdleConns(5)

	if err := configure(db); err != nil {
		db.Close()
		return nil, err
	}

	if err := Migrate(db); err != nil {
		db.Close()
		return nil, err
	}

	return db, nil
}

func configure(db *sql.DB) error {
	pragmas := []string{
		"PRAGMA journal_mode = WAL;",
		"PRAGMA synchronous = NORMAL;",
		"PRAGMA busy_timeout = 5000;",
		"PRAGMA foreign_keys = ON;",
	}

	for _, pragma := range pragmas {
		if _, err := db.Exec(pragma); err != nil {
			return fmt.Errorf(
				"setting pragma '%s': %w",
				pragma,
				err,
			)
		}
	}

	return nil
}

func Migrate(db *sql.DB) error {
	if err := createSchemaVersionTable(db); err != nil {
		return err
	}

	version, err := currentSchemaVersion(db)
	if err != nil {
		return err
	}

	pending, err := pendingMigrations(version)
	if err != nil {
		return err
	}

	for _, migration := range pending {
		if err := runMigration(db, migration.version, migration.filename); err != nil {
			return err
		}
	}

	return nil
}

func createSchemaVersionTable(db *sql.DB) error {
	_, err := db.Exec(`
		CREATE TABLE IF NOT EXISTS schema_version (
			id INTEGER PRIMARY KEY CHECK (id = 1),
			version INTEGER NOT NULL
		)
	`)
	if err != nil {
		return fmt.Errorf("creating schema_version table: %w", err)
	}

	return nil
}

func currentSchemaVersion(db *sql.DB) (int, error) {
	var version int

	err := db.QueryRow(`
		SELECT version
		FROM schema_version
		LIMIT 1
	`).Scan(&version)

	if err == sql.ErrNoRows {
		return 0, nil
	}

	if err != nil {
		return 0, fmt.Errorf("reading schema version: %w", err)
	}

	return version, nil
}

type migration struct {
	version  int
	filename string
}

func pendingMigrations(version int) ([]migration, error) {
	entries, err := migrations.ReadDir("migrations")
	if err != nil {
		return nil, fmt.Errorf("reading migrations directory: %w", err)
	}

	pending := make([]migration, 0)

	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".sql") {
			continue
		}

		parts := strings.SplitN(entry.Name(), "_", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid migration filename: %s", entry.Name())
		}

		migrationVersion, err := strconv.Atoi(parts[0])
		if err != nil {
			return nil, fmt.Errorf(
				"invalid migration version in %s: %w",
				entry.Name(),
				err,
			)
		}

		if migrationVersion > version {
			pending = append(pending, migration{
				version:  migrationVersion,
				filename: entry.Name(),
			})
		}
	}

	sort.Slice(pending, func(i, j int) bool {
		return pending[i].version < pending[j].version
	})

	return pending, nil
}

func runMigration(db *sql.DB, version int, filename string) error {
	sqlBytes, err := migrations.ReadFile(
		"migrations/" + filename,
	)
	if err != nil {
		return fmt.Errorf(
			"reading migration %s: %w",
			filename,
			err,
		)
	}

	tx, err := db.Begin()
	if err != nil {
		return fmt.Errorf(
			"starting migration %d: %w",
			version,
			err,
		)
	}

	if _, err := tx.Exec(string(sqlBytes)); err != nil {
		_ = tx.Rollback()

		return fmt.Errorf(
			"running migration %d (%s): %w",
			version,
			filename,
			err,
		)
	}

	_, err = tx.Exec(`
		INSERT INTO schema_version (id, version)
		VALUES (1, ?)
		ON CONFLICT(id) DO UPDATE SET version = excluded.version
	`, version)

	if err != nil {
		_ = tx.Rollback()

		return fmt.Errorf(
			"recording migration %d: %w",
			version,
			err,
		)
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf(
			"committing migration %d: %w",
			version,
			err,
		)
	}

	return nil
}



package server

import (
	"io/fs"
	"net/http"
	"path"
	"strings"

	"url-shortener/internal/link"
)

func WebHandler(files fs.FS, linkSvc link.Service) http.Handler {
	fileServer := http.FileServer(http.FS(files))

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := strings.TrimPrefix(path.Clean(r.URL.Path), "/")

		if p == "" {
			fileServer.ServeHTTP(w, r)
			return
		}

		l, extraPath, err := linkSvc.Resolve(r.Context(), p)
		if err == nil {
			dest := l.DestinationURL
			if extraPath != "" {
				dest = strings.TrimSuffix(dest, "/") + "/" + strings.TrimPrefix(extraPath, "/")
			}

			linkSvc.RecordClick(link.ClickEvent{
				LinkID:    l.ID,
				Referer:   r.Referer(),
				UserAgent: r.UserAgent(),
			})

			http.Redirect(w, r, dest, http.StatusFound)
			return
		}

		fileServer.ServeHTTP(w, r)
	})
}



package server

import (
	"io/fs"
	"net/http"

	"url-shortener/internal/link"
	"url-shortener/internal/middleware"
)

type Server struct {
	handler http.Handler
}

func NewServer(linkSvc link.Service, webFS fs.FS) *Server {
	mux := http.NewServeMux()

	linkHandler := link.NewHandler(linkSvc)
	linkHandler.RegisterRoutes(mux)

	mux.HandleFunc("GET /_health", handleHealth)

	mux.Handle("/", WebHandler(webFS, linkSvc))

	s := &Server{
		handler: middleware.Chain(mux, middleware.Recoverer, middleware.Logger),
	}
	return s
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.handler.ServeHTTP(w, r)
}



package link

import "time"

type Link struct {
	ID             int64      `json:"id"`
	Slug           string     `json:"slug"`
	DestinationURL string     `json:"destination_url"`
	IsCustom       bool       `json:"is_custom"`
	ClickCount     int64      `json:"click_count"`
	CreatedAt      time.Time  `json:"created_at"`
	ExpiresAt      *time.Time `json:"expires_at,omitempty"`
}

type ClickEvent struct {
	ID        int64     `json:"id"`
	LinkID    int64     `json:"link_id"`
	Referer   string    `json:"referer"`
	UserAgent string    `json:"user_agent"`
	ClickedAt time.Time `json:"clicked_at"`
}

type CreateLinkRequest struct {
	Slug           string     `json:"slug,omitempty"`
	DestinationURL string     `json:"destination_url"`
	ExpiresAt      *time.Time `json:"expires_at,omitempty"`
}
